-- =============================================================
--  Desafío Halloween - Base de datos (MySQL / MariaDB, XAMPP)
--  Importar desde phpMyAdmin > Importar, o ejecutar:
--      mysql -u root < halloween.sql
--  ATENCIÓN: borra y vuelve a crear la base "halloween".
-- =============================================================

SET NAMES utf8mb4;

DROP DATABASE IF EXISTS halloween;
CREATE DATABASE halloween CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE halloween;

-- Estructura pedida por la consigna. Se agregaron PRIMARY KEY, AUTO_INCREMENT,
-- claves UNIQUE y FOREIGN KEY para garantizar la integridad de los datos.
-- foto      = tipo MIME de la imagen (ej. image/png)
-- foto_blob = la imagen guardada en la base. Se usa MEDIUMBLOB (hasta 16 MB)
--             porque BLOB solo admite 64 KB, poco para una foto.
CREATE TABLE disfraces (
    id          INT(11)      NOT NULL AUTO_INCREMENT PRIMARY KEY,
    nombre      VARCHAR(50)  NOT NULL,
    descripcion TEXT         NOT NULL,
    votos       INT(11)      NOT NULL DEFAULT 0,
    foto        VARCHAR(20)  NOT NULL,
    foto_blob   MEDIUMBLOB   NOT NULL,
    eliminado   INT(11)      NOT NULL DEFAULT 0
) ENGINE=InnoDB;

-- clave guarda SIEMPRE el hash BCRYPT, nunca la contraseña en texto plano
CREATE TABLE usuarios (
    id      INT(11)     NOT NULL AUTO_INCREMENT PRIMARY KEY,
    nombre  VARCHAR(50) NOT NULL UNIQUE,
    clave   TEXT        NOT NULL
) ENGINE=InnoDB;

-- UNIQUE(id_usuario): un usuario = un voto, garantizado por la base
CREATE TABLE votos (
    id          INT(11) NOT NULL AUTO_INCREMENT PRIMARY KEY,
    id_usuario  INT(11) NOT NULL UNIQUE,
    id_disfraz  INT(11) NOT NULL,
    CONSTRAINT fk_votos_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios(id) ON DELETE CASCADE,
    CONSTRAINT fk_votos_disfraz FOREIGN KEY (id_disfraz) REFERENCES disfraces(id) ON DELETE CASCADE
) ENGINE=InnoDB;

